async function download(blob,name){if(isNative){try{const data=await blobToBase64(blob);const saved=await Filesystem.writeFile({path:name,data,directory:Directory.Cache});await Share.share({title:'Simpan '+name,text:name,url:saved.uri,dialogTitle:'Simpan atau bagikan file'});return true}catch(err){if(/cancel/i.test(String(err?.message||err)))return false;console.error(err);toast('Gagal menyiapkan file: '+(err?.message||err));return false}}const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);return true}
