let pinUnlocked=false,pinResolve=null,pinMode='verify',lastActive=Date.now();const RELOCK_MS=10*60*1000;
const bytesToHex=b=>Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('');
async function hashPin(pin,salt){const data=new TextEncoder().encode(`${salt}:${pin}`);return bytesToHex(await crypto.subtle.digest('SHA-256',data))}
function lockApp(){pinUnlocked=false}
const awayCheck=()=>{if(pinUnlocked&&Date.now()-lastActive>RELOCK_MS)lockApp()};
document.addEventListener('visibilitychange',()=>{if(document.hidden)lastActive=Date.now();else awayCheck()});
if(isNative)App.addListener('appStateChange',({isActive})=>{if(!isActive)lastActive=Date.now();else awayCheck()}).catch(()=>{});
function pinFinish(ok){const r=pinResolve;pinResolve=null;if($('pinDialog').open)$('pinDialog').close();if(r)r(ok)}
function openPinDialog(mode,reason){pinMode=mode;const dlg=$('pinDialog'),creating=mode!=='verify';$('pinEntry').value='';$('pinConfirm').value='';$('pinTitle').textContent=mode==='verify'?'Verifikasi PIN':mode==='change'?'Ganti PIN keamanan':'Buat PIN keamanan';$('pinMessage').textContent=mode==='verify'?`Masukkan PIN 6 digit untuk ${reason}.`:mode==='change'?'Masukkan PIN baru 6 angka, lalu ulangi.':'Buat PIN keamanan 6 digit untuk melindungi menu admin. PIN cukup dimasukkan satu kali setiap sesi.';$('pinConfirmLabel').hidden=!creating;$('pinConfirm').required=creating;if(dlg.open)dlg.close();return new Promise(res=>{pinResolve=res;dlg.showModal();$('pinEntry').focus()})}
async function requirePin(reason='Aksi admin'){if(pinUnlocked)return true;const s=(await all('settings')).find(x=>x.id==='main')||{};return openPinDialog(s.pinHash?'verify':'create',reason)}
$('pinCancel').onclick=()=>pinFinish(false);
$('pinDialog').addEventListener('close',()=>{if(pinResolve)pinFinish(false)});
$('pinForm').onsubmit=async e=>{e.preventDefault();const pin=$('pinEntry').value,s=(await all('settings')).find(x=>x.id==='main')||(await all('settings'))[0]||{};if(!/^\d{6}$/.test(pin)){toast('PIN harus tepat 6 angka');return}
if(pinMode==='verify'){if(await hashPin(pin,s.pinSalt)===s.pinHash){pinUnlocked=true;lastActive=Date.now();pinFinish(true);return}toast('PIN salah');$('pinEntry').value='';$('pinEntry').focus();return}
if(pin!==$('pinConfirm').value){toast('Konfirmasi PIN tidak sama');return}
const salt=bytesToHex(crypto.getRandomValues(new Uint8Array(16)));await put('settings',{...s,id:'main',pinSalt:salt,pinHash:await hashPin(pin,salt)});pinUnlocked=true;lastActive=Date.now();pinFinish(true);toast(pinMode==='change'?'PIN berhasil diperbarui':'PIN keamanan berhasil dibuat')};
$('changePin').onclick=async()=>{const s=(await all('settings')).find(x=>x.id==='main')||{};if(!s.pinHash){await requirePin('membuat PIN');return}if(!await requirePin('mengganti PIN'))return;await openPinDialog('change','')};
$('lockNow').onclick=()=>{lockApp();activatePage('dashboard');toast('Aplikasi dikunci. PIN diminta saat membuka menu terproteksi.')};

// ---- Customer management and CSV upsert ----
function csvParse(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field);rows.push(row);row=[];field=''}else if(c!=='\r')field+=c}row.push(field);if(row.some(x=>x!==''))rows.push(row);return rows}
function csvCell(v){let s=String(v??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function downloadText(text,name,type='text/csv;charset=utf-8'){return download(new Blob(['\ufeff'+text],{type}),name)}
async function renderCustomers(){let xs=await all('customers'),q=($('customerSearch')?.value||'').toLowerCase();xs=xs.filter(x=>(x.name+' '+x.phone+' '+x.code).toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));$('customerTable').innerHTML=table(xs.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.code||'')}</small></td><td>${esc(x.phone||'—')}</td><td>${esc(x.address||'—')}</td><td><button class="link" onclick="editCustomer('${x.id}')">Edit</button> <button class="link" onclick="deleteCustomer('${x.id}')">Hapus</button></td></tr>`),['Pelanggan','Nomor HP','Alamat','Aksi'])}
// Native Android contacts: safe upsert by normalized phone; preserve existing customer details.
function normalizePhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('0'))digits='62'+digits.slice(1);if(digits.startsWith('8'))digits='62'+digits;return digits}
$('syncPhoneContacts').onclick=async()=>{
  if(!isNative)return toast('Sinkronisasi kontak HP hanya tersedia pada aplikasi Android');
  const button=$('syncPhoneContacts');button.disabled=true;button.textContent='Membaca kontak…';
  try{
    const result=await PhoneContacts.getContacts();
    const contacts=Array.isArray(result?.contacts)?result.contacts:[];
    const current=await all('customers');let added=0,updated=0,skipped=0;
    const byPhone=new Map(current.filter(x=>x.phone).map(x=>[normalizePhone(x.phone),x]));
    for(const contact of contacts){
      const name=String(contact?.name||'').trim(),phone=String(contact?.phone||'').trim();
      if(!name||!phone){skipped++;continue}const key=normalizePhone(phone);if(!key){skipped++;continue}
      const old=byPhone.get(key);
      const obj={...(old||{}),id:old?.id||uid(),code:old?.code||'',name:old?.name||name,phone:old?.phone||phone,address:old?.address||'',email:old?.email||'',note:old?.note||'',phoneContactId:String(contact.contactId||'')};
      await put('customers',obj);if(old)updated++;else{added++;byPhone.set(key,obj)}
    }
    await renderCustomers();toast(`Kontak selesai: ${added} baru, ${updated} cocok, ${skipped} dilewati`);
  }catch(err){console.error('Sinkronisasi kontak gagal',err);toast('Sinkronisasi kontak gagal: '+(err?.message||err))}
  finally{button.disabled=false;button.textContent='↻ Sinkronkan Kontak HP'}
};

$('customerSearch').oninput=renderCustomers;$('addCustomer').onclick=()=>openCustomer();$('importCustomers').onclick=()=>$('customerCsv').click();$('customerTemplate').onclick=()=>downloadText('kode_pelanggan,nama,no_hp,alamat,email,keterangan\nDBL001,Contoh Pelanggan,081234567890,Alamat contoh,,Catatan\n','template-pelanggan-dbl.csv');
$('exportCustomers').onclick=async()=>{let xs=await all('customers'),head=['kode_pelanggan','nama','no_hp','alamat','email','keterangan'];downloadText([head.join(','),...xs.map(x=>[x.code,x.name,x.phone,x.address,x.email,x.note].map(csvCell).join(','))].join('\r\n'),'data-pelanggan-'+today()+'.csv')};
$('customerCsv').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;try{let rows=csvParse(await f.text());if(rows.length<2)throw Error('CSV tidak berisi baris data');let heads=rows.shift().map(x=>x.trim().toLowerCase().replace(/^\ufeff/,''));let idx=k=>heads.indexOf(k),get=(r,k)=>idx(k)>=0?(r[idx(k)]||'').trim():'';let current=await all('customers'),added=0,updated=0,errors=[];for(let n=0;n<rows.length;n++){let r=rows[n];if(!r.some(x=>x.trim()))continue;let name=get(r,'nama'),code=get(r,'kode_pelanggan'),phone=get(r,'no_hp').replace(/[\s-]/g,'');if(!name){errors.push(`Baris ${n+2}: nama kosong`);continue}let old=(code&&current.find(x=>x.code===code))||(phone&&current.find(x=>String(x.phone||'').replace(/[\s-]/g,'')===phone));let obj={...(old||{}),id:old?.id||uid(),code:code||old?.code||'',name,phone,address:get(r,'alamat'),email:get(r,'email'),note:get(r,'keterangan')};await put('customers',obj);if(old){updated++;current=current.map(x=>x.id===old.id?obj:x)}else{added++;current.push(obj)}}await renderCustomers();toast(`CSV selesai: ${added} baru, ${updated} diperbarui, ${errors.length} gagal`);if(errors.length)alert(errors.slice(0,20).join('\n'))}catch(err){toast('Import CSV gagal: '+err.message)}e.target.value=''};
async function openCustomer(id){if(id&&!await requirePin('mengubah pelanggan'))return;$('customerForm').reset();$('customerId').value=id||'';$('customerDialogTitle').textContent=id?'Edit pelanggan':'Tambah pelanggan';if(id)all('customers').then(xs=>{let x=xs.find(v=>v.id===id);if(!x)return;$('cCode').value=x.code||'';$('cName').value=x.name;$('cPhone').value=x.phone||'';$('cAddress').value=x.address||'';$('cEmail').value=x.email||'';$('cNote').value=x.note||'';$('customerDialog').showModal()});else $('customerDialog').showModal()}
window.editCustomer=id=>openCustomer(id);window.deleteCustomer=async id=>{if(!await requirePin('menghapus pelanggan'))return;if(confirm('Hapus pelanggan?')){await del('customers',id);renderCustomers()}};
$('saveCustomer').onclick=async e=>{e.preventDefault();if(!$('customerForm').reportValidity())return;let id=$('customerId').value||uid();await put('customers',{id,code:$('cCode').value.trim(),name:$('cName').value.trim(),phone:$('cPhone').value.trim(),address:$('cAddress').value.trim(),email:$('cEmail').value.trim(),note:$('cNote').value.trim()});$('customerDialog').close();renderCustomers();toast('Pelanggan disimpan')};

