async function renderEmployees(){let es=(await all('employees')).sort((a,b)=>String(a.name).localeCompare(String(b.name)));if(!es.length){$('employeeTable').innerHTML='<div class="empty-state"><b>Belum ada karyawan</b><span>Tekan “＋ Tambah karyawan” untuk menambahkan data karyawan.</span></div>';return}let tbl=table(es.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.position||'—')}</td><td>${dmy(x.startDate)}</td><td>${esc(x.phone||'—')}</td><td>${esc(x.account||'—')}</td><td class="act"><button class="link" onclick="editEmployee('${x.id}')">Edit</button><button class="link danger-link" onclick="deleteEmployee('${x.id}')">Hapus</button></td></tr>`),['Nama','Posisi','Tanggal masuk','No. HP','No. rekening / e-wallet','Aksi']);let cards=es.map(x=>`<article class="exp-card"><div class="exp-card-top"><div><b>${esc(x.name)}</b><small>${esc(x.position||'—')} · masuk ${dmy(x.startDate)}</small></div></div><div class="emp-meta"><span>📞 ${esc(x.phone||'—')}</span><span>💳 ${esc(x.account||'—')}</span></div><div class="exp-card-actions"><button class="outline" onclick="editEmployee('${x.id}')">Edit</button><button class="outline danger" onclick="deleteEmployee('${x.id}')">Hapus</button></div></article>`).join('');$('employeeTable').innerHTML=`<div class="exp-desktop">${tbl}</div><div class="exp-cards">${cards}</div>`}
$('addEmployee').onclick=()=>openEmployee();
async function openEmployee(id){if(id&&!await requirePin('mengubah karyawan'))return;$('employeeForm').reset();$('employeeId').value=id||'';$('employeeDialogTitle').textContent=id?'Edit karyawan':'Tambah karyawan';if(id)all('employees').then(xs=>{let x=xs.find(y=>y.id===id);if(!x)return;$('employeeName').value=x.name;$('employeeStart').value=x.startDate||'';$('employeePosition').value=x.position||'';$('employeePhone').value=x.phone||'';$('employeeAccount').value=x.account||'';$('employeeDialog').showModal()});else $('employeeDialog').showModal()}
