// ---- Edit & hapus transaksi (Riwayat) ----
let txEditItems=[],txEditOrig=null;
const toInputTime=t=>{const m=/^(\d{1,2})[.:](\d{2})/.exec(String(t||''));return m?`${m[1].padStart(2,'0')}:${m[2]}`:''};
function txEditTotals(){const sub=txEditItems.reduce((a,i)=>a+(Number(i.price)||0)*(Number(i.qty)||0),0),disc=Math.max(0,Number($('editTxDiscount').value)||0);return{sub,disc,total:Math.max(0,sub-disc)}}
function drawTxEditSummary(){const t=txEditTotals();$('editTxSummary').innerHTML=`<div class="kv"><span>Subtotal</span><b>${rupiah(t.sub)}</b></div><div class="kv"><span>Diskon</span><b>− ${rupiah(t.disc)}</b></div><div class="kv total"><span>Total</span><b>${rupiah(t.total)}</b></div>`}
function drawTxEditItems(){$('editTxItems').innerHTML=txEditItems.length?txEditItems.map((x,i)=>`<div class="te-row"><div class="te-name"><b>${esc(x.name)}</b><small class="sku">SKU: ${esc(x.sku||'—')}</small></div><div class="te-ctl"><button type="button" data-te="dec" data-i="${i}" aria-label="Kurangi">−</button><input type="number" class="te-qty" data-te="qty" data-i="${i}" min="0.01" step="any" inputmode="decimal" value="${x.qty}" aria-label="Jumlah"><button type="button" data-te="inc" data-i="${i}" aria-label="Tambah">＋</button></div><label class="te-price">Harga<input type="number" data-te="price" data-i="${i}" min="0" step="any" inputmode="decimal" value="${x.price}"></label><button type="button" class="link danger-link" data-te="rm" data-i="${i}">Hapus</button></div>`).join(''):'<div class="empty">Semua item dihapus. Tambahkan produk, atau hapus transaksi.</div>';drawTxEditSummary()}
$('editTxItems').addEventListener('click',e=>{const b=e.target.closest('[data-te]');if(!b||b.tagName!=='BUTTON')return;const i=Number(b.dataset.i),it=txEditItems[i];if(!it)return;if(b.dataset.te==='inc')it.qty=(Number(it.qty)||0)+1;else if(b.dataset.te==='dec')it.qty=Math.max(1,(Number(it.qty)||1)-1);else if(b.dataset.te==='rm')txEditItems.splice(i,1);drawTxEditItems()});
$('editTxItems').addEventListener('change',e=>{const f=e.target.closest('[data-te]');if(!f||f.tagName!=='INPUT')return;const it=txEditItems[Number(f.dataset.i)];if(!it)return;const v=Number(f.value);if(f.dataset.te==='qty')it.qty=v>0?v:1;else if(f.dataset.te==='price')it.price=v>=0?v:0;drawTxEditItems()});
$('editTxAddBtn').onclick=async()=>{const id=$('editTxAddProduct').value;if(!id)return toast('Pilih produk dulu');const p=(await all('products')).find(x=>x.id===id);if(!p)return;const ex=txEditItems.find(x=>x.productId===id);if(ex)ex.qty=(Number(ex.qty)||0)+1;else txEditItems.push({productId:p.id,name:p.name,price:p.price,costPrice:p.costPrice||0,sku:p.sku||'',qty:1,category:p.category});$('editTxAddProduct').value='';drawTxEditItems()};
$('editTxDiscount').addEventListener('input',drawTxEditSummary);
$('editTxPayment').addEventListener('change',()=>{$('editTxPaidLabel').hidden=$('editTxPayment').value!=='Tunai'});
async function openTransactionEdit(tx){if(!await requirePin('mengedit transaksi'))return;tx=(await all('transactions')).find(x=>x.id===tx.id)||tx;txEditOrig=tx;txEditItems=(tx.items||[]).map(x=>({...x}));
const cs=(await all('cashiers')).map(c=>c.name);if(tx.cashier&&!cs.includes(tx.cashier))cs.push(tx.cashier);$('editTxCashier').innerHTML=cs.map(n=>`<option>${esc(n)}</option>`).join('');$('editTxCashier').value=tx.cashier||cs[0]||'';
$('editTxAddProduct').innerHTML='<option value="">— Pilih produk —</option>'+(await all('products')).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.sku?` [${esc(p.sku)}]`:''}</option>`).join('');
$('editTxId').value=tx.id;$('editTxTitle').textContent='Edit transaksi '+tx.invoice;$('editTxDate').value=tx.date;$('editTxTime').value=toInputTime(tx.time);$('editTxType').value=tx.type||'Dine In';$('editTxCustomer').value=tx.customer||'';$('editTxDiscount').value=tx.discount||0;$('editTxPayment').value=tx.payment;$('editTxPaid').value=tx.paid||0;$('editTxPaidLabel').hidden=tx.payment!=='Tunai';$('editTxNote').value=tx.note||'';drawTxEditItems();if($('detailDialog').open)$('detailDialog').close();$('editTxDialog').showModal()}
// Selisih stok produk: jumlah lama - jumlah baru (positif = stok dikembalikan). Hanya produk yang stoknya dilacak.
async function applyStockDelta(oldItems,newItems){const ps=await all('products'),delta=new Map();const key=it=>{const p=ps.find(x=>x.id===it.productId)||ps.find(x=>BK.normSku(x.sku)&&BK.normSku(x.sku)===BK.normSku(it.sku));return p?.id};for(const it of oldItems||[]){const k=key(it);if(k)delta.set(k,(delta.get(k)||0)+(Number(it.qty)||0))}for(const it of newItems||[]){const k=key(it);if(k)delta.set(k,(delta.get(k)||0)-(Number(it.qty)||0))}
for(const [id,d] of delta){if(!d)continue;const p=ps.find(x=>x.id===id);if(!p||p.stock===null||p.stock===undefined||p.stock==='')continue;await put('products',{...p,stock:Math.max(0,Math.round((Number(p.stock)+d)*1000)/1000)})}}
$('saveTxEdit').onclick=async e=>{e.preventDefault();const tx=(await all('transactions')).find(x=>x.id===$('editTxId').value);if(!tx)return;
if(!txEditItems.length)return toast('Transaksi harus punya minimal satu item (atau hapus transaksi)');if(!$('editTxDate').value)return toast('Isi tanggal');
const t=txEditTotals();if(t.disc>t.sub)return toast('Diskon melebihi subtotal');const payment=$('editTxPayment').value,paid=payment==='Tempo / Kasbon'?0:payment==='Tunai'?Math.max(0,Number($('editTxPaid').value)||0):t.total;if(payment==='Tunai'&&paid<t.total)return toast('Uang diterima kurang dari total');if(payment==='Tempo / Kasbon'&&!$('editTxCustomer').value.trim())return toast('Isi nama pelanggan untuk transaksi Tempo / Kasbon');
const rec=(await all('receivables')).find(x=>x.id==='tx-'+tx.id);if(rec&&BK.paidOf(rec)>0){if(payment!=='Tempo / Kasbon')return toast('Piutang nota ini sudah ada pembayaran; hapus pembayarannya dulu');if(BK.paidOf(rec)>t.total)return toast('Total baru lebih kecil dari pembayaran piutang yang sudah tercatat')}
if(!await requirePin('menyimpan perubahan transaksi'))return;
const newTime=$('editTxTime').value,timeChanged=newTime&&newTime!==toInputTime(tx.time),items=txEditItems.map(x=>({...x,qty:Number(x.qty)||1,price:Number(x.price)||0}));
const txNew={...tx,items,date:$('editTxDate').value,time:timeChanged?newTime.replace(':','.')+'.00':tx.time,type:$('editTxType').value,cashier:$('editTxCashier').value||tx.cashier,customer:$('editTxCustomer').value.trim(),subtotal:t.sub,discount:t.disc,total:t.total,payment,paid,change:Math.max(0,paid-t.total),note:$('editTxNote').value.trim(),updatedAt:Date.now(),edited:true};
await applyStockDelta(tx.items,items);await put('transactions',txNew);await syncTxReceivable(txNew);
await window.invSyncSale?.(tx.date);if(txNew.date!==tx.date)await window.invSyncSale?.(txNew.date);
$('editTxDialog').close();await refreshAll();toast('Transaksi '+tx.invoice+' diperbarui');};
async function deleteTransaction(id){const tx=(await all('transactions')).find(x=>x.id===id);if(!tx)return;if(!await requirePin('menghapus transaksi'))return;
const rec=(await all('receivables')).find(x=>x.id==='tx-'+tx.id),paidRec=rec?BK.paidOf(rec):0;
const msg=`Hapus transaksi ${tx.invoice} (${rupiah(tx.total)}, ${dmy(tx.date)})?\n\nStok produk dikembalikan, penjualan hilang dari laporan, dan catatan Persediaan terkait diperbarui.${paidRec>0?`\n\nPiutang nota ini sudah dibayar ${rupiah(paidRec)}; pembayarannya ikut terhapus dari buku kas.`:''}\n\nTindakan ini tidak dapat dibatalkan.`;
if(!confirm(msg))return;
await applyStockDelta(tx.items,[]);if(rec)await del('receivables',rec.id);await del('transactions',tx.id);await window.invSyncSale?.(tx.date);
if($('editTxDialog').open)$('editTxDialog').close();if($('detailDialog').open)$('detailDialog').close();await refreshAll();toast('Transaksi '+tx.invoice+' dihapus')}
$('editTxDelete').onclick=()=>deleteTransaction($('editTxId').value);
window.editTransactionById=async id=>{const tx=(await all('transactions')).find(x=>x.id===id);if(tx)openTransactionEdit(tx)};
window.deleteTransaction=deleteTransaction;

// ---- WhatsApp/shareable receipt PDF ----
async function shareReceipt(tx){try{const doc=await window.receiptApi.pdf(tx);const blob=doc.output('blob'),base64=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)});let fileName=`struk-${tx.invoice}.pdf`;if(isNative){let saved=await Filesystem.writeFile({path:fileName,data:base64,directory:Directory.Cache});await Share.share({title:`Struk ${tx.invoice}`,text:`Struk transaksi ${tx.invoice}`,url:saved.uri,dialogTitle:'Bagikan struk — pilih WhatsApp'});}else{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('PDF struk diunduh; lampirkan melalui WhatsApp')}}catch(err){toast('Gagal membagikan struk: '+err.message)}}

// ---- Bluetooth Classic SPP ESC/POS for paired RPP02N ----
let printerConnected=false;
async function refreshPrinters(){try{let r=await BluetoothSerial.listPairedDevices(),devices=r.devices||[];$('printerSelect').innerHTML='<option value="">Pilih printer</option>'+devices.map(d=>`<option value="${esc(d.address)}">${esc(d.name||'Bluetooth')} — ${esc(d.address)}</option>`).join('');let match=devices.find(d=>/RPP02N/i.test(d.name||''));if(match)$('printerSelect').value=match.address;$('printerStatus').textContent=devices.length?`${devices.length} perangkat dipasangkan`:'Tidak ada perangkat dipasangkan';}catch(err){$('printerStatus').textContent='Bluetooth tidak tersedia: '+err.message;toast('Pastikan Bluetooth aktif dan printer dipasangkan di Android')}}
$('refreshPrinters').onclick=refreshPrinters;
$('connectPrinter').onclick=async()=>{let address=$('printerSelect').value;if(!address)return toast('Pilih printer terlebih dahulu');try{await BluetoothSerial.connect({address});printerConnected=true;$('printerStatus').textContent='Terhubung ke '+$('printerSelect').selectedOptions[0].text;toast('Printer terhubung')}catch(err){printerConnected=false;toast('Gagal menghubungkan printer: '+err.message)}};
async function escposBytes(tx,cfg){return window.receiptApi.escBase64(tx,cfg)}
async function printReceiptBluetooth(tx,cfg){if(!printerConnected)throw Error('Hubungkan printer Bluetooth terlebih dahulu');const data=await escposBytes(tx,cfg),n=await window.receiptApi.copies();for(let i=0;i<n;i++)await BluetoothSerial.print({data})}
async function printReceiptBluetoothWith(tx,cfg){try{await printReceiptBluetooth(tx,cfg);toast('Struk dikirim ke printer')}catch(e){toast('Cetak Bluetooth gagal: '+e.message)}}
const originalPrintReceipt=printReceipt;printReceipt=async tx=>{if(printerConnected){try{await printReceiptBluetooth(tx);toast('Struk dikirim ke printer RPP02N')}catch(e){toast('Cetak Bluetooth gagal: '+e.message)}}else originalPrintReceipt(tx)};
$('printLast').onclick=()=>lastReceipt?printReceipt(lastReceipt):toast('Belum ada transaksi pada sesi ini');

