Object.assign(window,{editExpense,renderProducts});
window.KSfix={syncTxReceivable,syncExpenseDebt};
window.editExpenseType=async encoded=>{let old=decodeURIComponent(encoded);if(!await requirePin('mengubah jenis pengeluaran'))return;let n=prompt('Nama jenis baru',old);if(!n||n.trim()===old)return;n=n.trim();let {s,types,items}=await getExpenseMasters();if(types.includes(n))return toast('Nama jenis sudah ada');types=types.map(x=>x===old?n:x);items[n]=items[old]||[];delete items[old];let g={...(s.expenseGroups||{})};g[n]=g[old]||defaultExpenseGroup(old);delete g[old];await saveExpenseMasters(types,items,{...s,expenseGroups:g});for(let x of await all('expenses'))if(x.type===old)await put('expenses',{...x,type:n});renderExpenseMasters();renderExpenses();toast('Jenis diubah')};
window.deleteExpenseType=async encoded=>{let t=decodeURIComponent(encoded);if(!await requirePin('menghapus jenis pengeluaran'))return;if(!confirm(`Hapus jenis ${t} dari master? Catatan lama dipertahankan.`))return;let {s,types,items}=await getExpenseMasters();types=types.filter(x=>x!==t);delete items[t];await saveExpenseMasters(types,items,s);renderExpenseMasters();toast('Jenis dihapus dari master')};
window.editExpenseMasterItem=async(encodedT,encodedOld)=>{let t=decodeURIComponent(encodedT),old=decodeURIComponent(encodedOld);if(!await requirePin('mengubah item pengeluaran'))return;let n=prompt('Nama item baru',old);if(!n||n.trim()===old)return;n=n.trim();let {s,types,items}=await getExpenseMasters();if((items[t]||[]).includes(n))return toast('Item sudah ada');items[t]=(items[t]||[]).map(x=>x===old?n:x);await saveExpenseMasters(types,items,s);for(let x of await all('expenses'))if(x.type===t&&x.name===old)await put('expenses',{...x,name:n});renderExpenseMasters();renderExpenses();toast('Item diubah')};
window.deleteExpenseMasterItem=async(encodedT,encodedI)=>{let t=decodeURIComponent(encodedT),i=decodeURIComponent(encodedI);if(!await requirePin('menghapus item pengeluaran'))return;if(!confirm(`Hapus item ${i} dari master? Catatan lama dipertahankan.`))return;let {s,types,items}=await getExpenseMasters();items[t]=(items[t]||[]).filter(x=>x!==i);await saveExpenseMasters(types,items,s);renderExpenseMasters();toast('Item dihapus dari master')};
$('profitReveal')?.addEventListener('click',async()=>{if($('profitReveal').dataset.visible==='1'){$('todayProfit').textContent='••••••';$('profitReveal').textContent='Tampilkan (PIN)';$('profitReveal').dataset.visible='0';return}if(!await requirePin('melihat laba kotor hari ini'))return;$('todayProfit').textContent=profitValue||'Rp0';$('profitReveal').textContent='Sembunyikan';$('profitReveal').dataset.visible='1'});

// ================= KASIR 2.2.0 =================
const TEMPO=BK.TEMPO;
const monthLabel=ym=>{const [y,m]=String(ym).split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'})};
const blobToBase64=b=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(b)});
async function bookData(){const s=(await all('settings')).find(x=>x.id==='main')||{};const opening=(await all('openingBalance')).find(x=>x.id==='main')||{};return{opening,transactions:await all('transactions'),expenses:await all('expenses'),assets:await all('assets'),liabilities:await all('liabilities'),receivables:await all('receivables'),products:await all('products'),groups:s.expenseGroups||{}}}
const exportXlsx=(sheets,name)=>download(buildXlsx(sheets),name);
// tombol Batal / X di semua dialog (sebelumnya tertahan validasi form sehingga hanya tombol back yang berfungsi)
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-close]');if(!b)return;e.preventDefault();b.closest('dialog')?.close()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('dialog[open]')?.close()});
window.KS={all,put,del,rupiah,esc,today,toast,requirePin,showPage,download,exportXlsx,bookData,monthLabel,table};
Object.assign(window,{bookData,requirePin,rupiah,esc,today,exportXlsx,download,monthLabel,table,activatePage});

// ---- migrasi data lama ----
async function migrateData(){try{const ps=await all('products');for(const p of ps){if(!BK.normSku(p.sku)){p.sku=BK.nextSku(ps);await put('products',p)}}
for(const it of await all('invItems')){if(!it.sku&&it.productId){const p=ps.find(x=>x.id===it.productId);if(p?.sku)await put('invItems',{...it,sku:p.sku})}}
{const s=(await all('settings')).find(x=>x.id==='main');if(s&&!s.hppV2){const g={...(s.expenseGroups||{})};for(const t of ['Utilitas','Transportasi'])if((s.expenseTypes||[]).includes(t)&&(!g[t]||g[t]==='operasional'))g[t]='beban';await put('settings',{...s,expenseGroups:g,hppV2:true})}}
if(!(await all('cashiers')).length)await put('cashiers',{id:'pemilik',name:'Pemilik',createdAt:Date.now()})}catch(err){console.warn('Migrasi data gagal',err)}}

// ---- kasir ----
async function renderCashiers(){const xs=(await all('cashiers')).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0));const sel=$('cashier');if(sel){const cur=sel.value,s=(await all('settings')).find(x=>x.id==='main')||{},want=cur||s.lastCashier;sel.innerHTML=xs.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('')||'<option value="Pemilik">Pemilik</option>';if([...sel.options].some(o=>o.value===want))sel.value=want;$('cashierName').textContent=sel.value}
const box=$('cashierList');if(box)box.innerHTML=xs.length?xs.map(c=>`<div class="cashier-row"><div><b>${esc(c.name)}</b>${c.phone?`<small>${esc(c.phone)}</small>`:''}</div><div><button class="link" onclick="editCashier('${c.id}')">Edit</button><button class="link danger-link" onclick="deleteCashier('${c.id}')">Hapus</button></div></div>`).join(''):'<div class="empty">Belum ada kasir.</div>'}
$('cashier').onchange=async()=>{$('cashierName').textContent=$('cashier').value;const s=(await all('settings')).find(x=>x.id==='main')||{};await put('settings',{...s,id:'main',lastCashier:$('cashier').value})};
async function openCashier(id){$('cashierForm').reset();$('cashierId').value=id||'';$('cashierTitle').textContent=id?'Edit kasir':'Tambah kasir';if(id){const c=(await all('cashiers')).find(x=>x.id===id);if(c){$('cashierName').value=c.name;$('cashierPhone').value=c.phone||''}}$('cashierDialog').showModal();$('cashierName').focus()}
$('addCashier').onclick=()=>openCashier();
$('cashierSave').onclick=async e=>{e.preventDefault();if(!$('cashierForm').reportValidity())return;const name=$('cashierName').value.trim(),id=$('cashierId').value,xs=await all('cashiers');if(!name)return toast('Isi nama kasir');if(xs.some(c=>c.id!==id&&c.name.toLowerCase()===name.toLowerCase()))return toast('Nama kasir sudah ada');const old=xs.find(c=>c.id===id)||{};await put('cashiers',{...old,id:id||uid(),name,phone:$('cashierPhone').value.trim(),createdAt:old.createdAt||Date.now()});$('cashierDialog').close();await renderCashiers();toast(id?'Kasir diperbarui':'Kasir ditambahkan')};
window.editCashier=openCashier;
window.deleteCashier=async id=>{const xs=await all('cashiers'),c=xs.find(x=>x.id===id);if(!c)return;if(xs.length<=1)return toast('Minimal harus ada satu kasir');if(confirm(`Hapus kasir ${c.name}? Riwayat transaksi tetap tersimpan.`)){await del('cashiers',id);await renderCashiers();toast('Kasir dihapus')}};

// ---- stok produk, piutang & hutang otomatis ----
async function lowStockLines(items){const ps=await all('products'),out=[];for(const it of items){const p=ps.find(x=>x.id===it.productId)||BK.findProductBySku(ps,it.sku);if(p&&p.stock!==null&&p.stock!==undefined&&p.stock!==''&&Number(it.qty)>Number(p.stock))out.push(`${p.name}: stok ${p.stock}, dijual ${it.qty}`)}return out}
async function afterSale(tx){const ps=await all('products');for(const it of tx.items){const i=ps.findIndex(x=>x.id===it.productId);const k=i>=0?i:ps.findIndex(x=>BK.normSku(x.sku)&&BK.normSku(x.sku)===BK.normSku(it.sku));if(k<0)continue;const p=ps[k];if(p.stock===null||p.stock===undefined||p.stock==='')continue;ps[k]={...p,stock:Math.max(0,Number(p.stock)-(Number(it.qty)||0))};await put('products',ps[k])}
await syncTxReceivable(tx);await window.invSyncSale?.(tx.date)}
async function syncTxReceivable(tx){const id='tx-'+tx.id,ex=(await all('receivables')).find(x=>x.id===id);if(tx.payment===TEMPO){await put('receivables',{...(ex||{}),id,txId:tx.id,auto:true,kind:'Piutang Pelanggan',name:tx.customer||'Pelanggan umum',amount:Number(tx.total)||0,date:tx.date,due:ex?.due||'',note:'Nota '+tx.invoice,payments:ex?.payments||[],createdAt:ex?.createdAt||Date.now()})}else if(ex)await del('receivables',id)}
async function syncExpenseDebt(exp){const id='ex-'+exp.id,ex=(await all('liabilities')).find(x=>x.id===id);if(exp.payment==='Hutang'){if(ex&&BK.paidOf(ex)>Number(exp.amount)){toast('Nominal lebih kecil dari pembayaran hutang yang sudah tercatat');return false}await put('liabilities',{...(ex||{}),id,expenseId:exp.id,auto:true,kind:'Hutang Supplier',name:exp.name,amount:Number(exp.amount)||0,date:exp.date,due:ex?.due||'',note:[exp.type,exp.note].filter(Boolean).join(' · '),payments:ex?.payments||[],createdAt:ex?.createdAt||Date.now()});return true}
if(ex){if(BK.paidOf(ex)>0){toast('Hutang terkait sudah ada pembayaran; metode bayar tidak dapat diubah');return false}await del('liabilities',id)}return true}
async function removeExpenseDebt(expId){const ex=(await all('liabilities')).find(x=>x.id==='ex-'+expId);if(!ex)return true;if(BK.paidOf(ex)>0&&!confirm('Hutang terkait pengeluaran ini sudah ada pembayaran. Tetap hapus keduanya?'))return false;await del('liabilities',ex.id);return true}

// ---- aset & penyusutan ----
async function renderAssets(){if(!$('assetTable'))return;const d=await bookData(),xs=d.assets.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let tv=0,tm=0,ta=0,tb=0;const rows=xs.map(x=>{const i=BK.assetInfo(x);tv+=Number(x.value)||0;tm+=i.monthly;ta+=i.accum;tb+=i.book;return `<tr><td><b>${esc(x.name)}</b><small>${dmy(x.date)} · umur ${Number(x.life)||1} th</small></td><td class="num">${rupiah(x.value)}</td><td class="num">${rupiah(i.monthly)}</td><td class="num">${rupiah(i.annual)}</td><td class="num">${rupiah(i.accum)}</td><td class="num"><b>${rupiah(i.book)}</b></td><td class="act"><button class="link" onclick="editAsset('${x.id}')">Edit</button><button class="link danger-link" onclick="deleteAsset('${x.id}')">Hapus</button></td></tr>`});
$('assetStats').innerHTML=`<article><small>Harga perolehan</small><strong>${rupiah(tv)}</strong><span>${xs.length} aset</span></article><article><small>Susut / bulan</small><strong>${rupiah(tm)}</strong><span>beban penyusutan</span></article><article><small>Nilai buku</small><strong>${rupiah(tb)}</strong><span>setelah akumulasi ${rupiah(ta)}</span></article>`;
const cards=xs.map(x=>{const i=BK.assetInfo(x);return `<div class="dc-card"><div class="top"><b>${esc(x.name)}</b></div><small>Dibeli ${dmy(x.date)} · umur ${Number(x.life)||1} tahun · akumulasi ${rupiah(i.accum)}</small><div class="dc-grid"><div><small>Harga perolehan</small><b>${rupiah(x.value)}</b></div><div><small>Susut / bulan</small><b>${rupiah(i.monthly)}</b></div><div><small>Nilai buku</small><b>${rupiah(i.book)}</b></div></div><div class="dc-act"><button onclick="editAsset('${x.id}')">Edit</button><button onclick="deleteAsset('${x.id}')">Hapus</button></div></div>`}).join('');
$('assetTable').innerHTML=`<div class="dc-table">${table(rows,['Aset','Harga perolehan','Susut / bulan','Susut / tahun','Akumulasi s.d. bulan ini','Nilai buku','Aksi'])}</div><div class="dc-cards">${cards||'<div class="empty">Belum ada data.</div>'}</div>`}
async function openAsset(id){if(id&&!await requirePin('mengubah aset'))return;if(!id&&!await requirePin('menambah aset'))return;const o=BK.normOpening((await bookData()).opening);$('assetForm').reset();$('assetForm').dataset.editId=id||'';$('assetResidual').dataset.touched='';$('assetDate').value=today();$('assetLife').value=o.life;$('assetResidual').value=0;$('assetCash').checked=!!o.date&&today()>=o.date;document.querySelector('#assetDialog h2').textContent=id?'Edit aset':'Tambah aset';if(id){const x=(await all('assets')).find(a=>a.id===id);if(x){$('assetName').value=x.name;$('assetDate').value=x.date;$('assetValue').value=x.value;$('assetLife').value=x.life;$('assetResidual').value=x.residual||0;$('assetResidual').dataset.touched='1';$('assetCash').checked=!!x.cashPaid}}$('assetDialog').showModal()}
$('assetAdd')?.addEventListener('click',()=>openAsset());
$('assetResidual').addEventListener('input',()=>{$('assetResidual').dataset.touched='1'});
$('assetValue').addEventListener('input',async()=>{if($('assetResidual').dataset.touched==='1')return;const o=BK.normOpening((await bookData()).opening);$('assetResidual').value=Math.round((Number($('assetValue').value)||0)*o.residualPct/100)});
$('assetSave')?.addEventListener('click',async e=>{e.preventDefault();if(!$('assetForm').reportValidity())return;const value=Number($('assetValue').value)||0,residual=Number($('assetResidual').value)||0,life=Number($('assetLife').value)||0;if(value<=0||life<=0||residual>value)return toast('Periksa nilai aset, residu dan umur manfaat');const id=$('assetForm').dataset.editId||'',old=id?(await all('assets')).find(a=>a.id===id)||{}:{};await put('assets',{...old,id:id||uid(),name:$('assetName').value.trim(),date:$('assetDate').value,value,life,residual,cashPaid:$('assetCash').checked,createdAt:old.createdAt||Date.now()});$('assetDialog').close();await renderAssets();toast('Aset tersimpan')});
window.editAsset=openAsset;window.deleteAsset=async id=>{if(!await requirePin('menghapus aset'))return;if(confirm('Hapus catatan aset?')){await del('assets',id);renderAssets()}};
$('exportAssets').onclick=async()=>{const d=await bookData(),xs=d.assets.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));const st=(await all('settings')).find(x=>x.id==='main')||{};let tv=0,tm=0,ta=0,tb=0;const rows=xs.map((x,i)=>{const f=BK.assetInfo(x);tv+=Number(x.value)||0;tm+=f.monthly;ta+=f.accum;tb+=f.book;return[i+1,x.name,{d:x.date},{rp:Number(x.value)||0},Number(x.life)||1,{rp:Number(x.residual)||0},{rp:Math.round(f.monthly)},{rp:Math.round(f.annual)},{rp:Math.round(f.accum)},{rp:Math.round(f.book)}]});
await exportXlsx([{name:'Aset Penyusutan',title:'Daftar Aset & Penyusutan — '+(st.name||'Usaha'),note:'Per '+dmy(today())+'. Penyusutan garis lurus: (harga − nilai sisa) ÷ (umur × 12) per bulan.',widths:[6,32,13,18,10,16,18,18,20,18],rows:[[{h:'No'},{h:'Nama aset'},{h:'Tanggal beli'},{h:'Harga perolehan (Rp)'},{h:'Umur (tahun)'},{h:'Nilai sisa (Rp)'},{h:'Penyusutan / bulan (Rp)'},{h:'Penyusutan / tahun (Rp)'},{h:'Akumulasi s.d. bulan ini (Rp)'},{h:'Nilai buku (Rp)'}],...rows,[{b:'TOTAL'},null,null,{brp:tv},null,null,{brp:Math.round(tm)},{brp:Math.round(tm*12)},{brp:Math.round(ta)},{brp:Math.round(tb)}]]}],'aset-penyusutan-'+today()+'.xlsx');toast('Laporan aset siap diunduh')};

// ---- hutang & piutang (dengan pembayaran) ----
async function debtRows(){const d=await bookData();return[...d.liabilities.map(x=>({...x,entryType:'debt',kind:x.kind||'Hutang Supplier'})),...d.receivables.map(x=>({...x,entryType:'receivable',kind:x.kind||'Piutang Pelanggan'}))].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')))}
async function renderDebts(){if(!$('debtTable'))return;let xs=await debtRows();const all0=xs,filter=$('debtType')?.value||'all';if(filter!=='all')xs=xs.filter(x=>x.entryType===filter);const sum=(l,t)=>l.filter(x=>x.entryType===t).reduce((a,x)=>a+BK.remainOf(x),0),od=all0.filter(x=>BK.debtStatus(x)==='Jatuh tempo').length;
$('debtStats').innerHTML=`<article><small>Sisa hutang supplier</small><strong>${rupiah(sum(all0,'debt'))}</strong><span>kewajiban belum dibayar</span></article><article><small>Sisa piutang + kasbon</small><strong>${rupiah(sum(all0,'receivable'))}</strong><span>tagihan belum diterima</span></article><article><small>Jatuh tempo</small><strong>${od}</strong><span>catatan lewat jatuh tempo</span></article>`;
const stCls=s=>s==='Lunas'?'good':s==='Jatuh tempo'?'bad':'mid';
const rows=xs.map(x=>`<tr><td>${esc(x.kind)}${x.auto?'<span class="debt-tag">otomatis</span>':''}</td><td><b>${esc(x.name)}</b><small>${dmy(x.date)} · jatuh tempo ${x.due?dmy(x.due):'—'}${x.note?' · '+esc(x.note):''}</small></td><td class="num">${rupiah(x.amount)}</td><td class="num">${rupiah(BK.paidOf(x))}</td><td class="num"><b>${rupiah(BK.remainOf(x))}</b></td><td><span class="status ${stCls(BK.debtStatus(x))}">${BK.debtStatus(x)}</span></td><td class="act"><button class="link" onclick="payDebt('${x.entryType}','${x.id}')">Bayar / Riwayat</button>${x.auto?'':`<button class="link danger-link" onclick="deleteDebt('${x.entryType}','${x.id}')">Hapus</button>`}</td></tr>`);
const cards=xs.map(x=>`<div class="dc-card"><div class="top"><b>${esc(x.name)}</b><span class="status ${stCls(BK.debtStatus(x))}">${BK.debtStatus(x)}</span></div><small>${esc(x.kind)}${x.auto?' · otomatis':''} · ${dmy(x.date)} · jatuh tempo ${x.due?dmy(x.due):'—'}${x.note?' · '+esc(x.note):''}</small><div class="dc-grid"><div><small>Nominal</small><b>${rupiah(x.amount)}</b></div><div><small>Dibayar</small><b>${rupiah(BK.paidOf(x))}</b></div><div><small>Sisa</small><b>${rupiah(BK.remainOf(x))}</b></div></div><div class="dc-act">${x.auto?'':`<button onclick="deleteDebt('${x.entryType}','${x.id}')">Hapus</button>`}<button class="primary" onclick="payDebt('${x.entryType}','${x.id}')">${x.entryType==='debt'?'Bayar':'Terima'} / Riwayat</button></div></div>`).join('');
$('debtTable').innerHTML=`<div class="dc-table">${table(rows,['Jenis','Pihak / Tanggal','Nominal','Dibayar','Sisa','Status','Aksi'])}</div><div class="dc-cards">${cards||'<div class="empty">Belum ada data.</div>'}</div>`}
$('debtAdd')?.addEventListener('click',async()=>{if(!await requirePin('menambah hutang/piutang'))return;$('debtForm').reset();$('debtDate').value=today();syncDebtCashRow();$('debtDialog').showModal()});
function syncDebtCashRow(){const k=$('debtEntryType').value,row=$('debtCashRow');row.hidden=k==='Piutang Pelanggan';$('debtCash').checked=k==='Kasbon Karyawan';$('debtCashLabel').textContent=k==='Kasbon Karyawan'?'Uang kasbon keluar dari kas saat dicatat':'Dana pinjaman diterima masuk ke kas saat dicatat'}
$('debtEntryType').addEventListener('change',syncDebtCashRow);
$('debtSave')?.addEventListener('click',async e=>{e.preventDefault();if(!$('debtForm').reportValidity())return;const kind=$('debtEntryType').value,store=kind==='Hutang Supplier'?'liabilities':'receivables',amount=Number($('debtAmount').value)||0;if(amount<=0)return toast('Nominal harus lebih dari 0');await put(store,{id:uid(),kind,name:$('debtName').value.trim(),amount,date:$('debtDate').value,due:$('debtDue').value,note:$('debtNote').value.trim(),cashAtCreate:kind!=='Piutang Pelanggan'&&$('debtCash').checked,payments:[],createdAt:Date.now()});$('debtDialog').close();await renderDebts();toast('Catatan tersimpan')});
$('debtType')?.addEventListener('change',renderDebts);
window.deleteDebt=async(type,id)=>{if(!await requirePin('menghapus catatan'))return;const store=type==='debt'?'liabilities':'receivables',x=(await all(store)).find(v=>v.id===id);if(confirm(x&&BK.paidOf(x)>0?'Catatan ini sudah memiliki pembayaran yang ikut terhapus dari buku kas. Hapus?':'Hapus catatan?')){await del(store,id);renderDebts()}};
async function openPay(type,id){const store=type==='debt'?'liabilities':'receivables',x=(await all(store)).find(v=>v.id===id);if(!x)return;$('payType').value=type;$('payId').value=id;$('payTitle').textContent=type==='debt'?'Bayar hutang':'Terima pembayaran piutang';const remain=BK.remainOf(x);$('paySummary').innerHTML=`<b>${esc(x.name)}</b> · ${esc(x.kind||'')}<br>Nominal ${rupiah(x.amount)} · dibayar ${rupiah(BK.paidOf(x))} · <b>sisa ${rupiah(remain)}</b>`;$('payAmount').value=remain||'';$('payDate').value=today();$('payMethod').value='Tunai';$('paySave').disabled=remain<=0;$('payHistory').innerHTML=(x.payments||[]).length?`<div class="pay-hist"><b>Riwayat pembayaran</b>${x.payments.map(p=>`<div><span>${dmy(p.date)} · ${esc(p.method||'Tunai')}</span><span>${rupiah(p.amount)} <button type="button" class="link danger-link" onclick="delPayment('${type}','${id}','${p.id}')">Hapus</button></span></div>`).join('')}</div>`:'';if(!$('payDialog').open)$('payDialog').showModal()}
window.payDebt=openPay;
window.delPayment=async(type,id,pid)=>{const store=type==='debt'?'liabilities':'receivables',x=(await all(store)).find(v=>v.id===id);if(!x||!confirm('Hapus pembayaran ini? Buku kas ikut berubah.'))return;await put(store,{...x,payments:(x.payments||[]).filter(p=>p.id!==pid)});await openPay(type,id);renderDebts()};
$('paySave').onclick=async e=>{e.preventDefault();const type=$('payType').value,id=$('payId').value,store=type==='debt'?'liabilities':'receivables',x=(await all(store)).find(v=>v.id===id);if(!x)return;const amount=Number($('payAmount').value)||0;if(amount<=0)return toast('Nominal harus lebih dari 0');if(!$('payDate').value)return toast('Isi tanggal');if(amount>BK.remainOf(x)+0.001)return toast('Nominal melebihi sisa '+rupiah(BK.remainOf(x)));await put(store,{...x,payments:[...(x.payments||[]),{id:uid(),date:$('payDate').value,amount,method:$('payMethod').value}]});$('payDialog').close();await renderDebts();toast(type==='debt'?'Pembayaran hutang dicatat (kas keluar)':'Pembayaran piutang dicatat (kas masuk)')};
$('exportDebts').onclick=async()=>{const xs=await debtRows(),st=(await all('settings')).find(x=>x.id==='main')||{};let ta=0,tp=0,tr=0;const rows=xs.map(x=>{ta+=Number(x.amount)||0;tp+=BK.paidOf(x);tr+=BK.remainOf(x);return[{d:x.date},x.kind,x.name,x.note||'',{rp:Number(x.amount)||0},x.due?{d:x.due}:'',{rp:BK.paidOf(x)},{rp:BK.remainOf(x)},BK.debtStatus(x)]});
const pays=[];xs.forEach(x=>(x.payments||[]).forEach(p=>pays.push([{d:p.date},x.kind,x.name,p.method||'Tunai',{rp:Number(p.amount)||0},x.entryType==='debt'?'Kas keluar':'Kas masuk'])));pays.sort((a,b)=>String(a[0].d).localeCompare(String(b[0].d)));
await exportXlsx([{name:'Hutang-Piutang',title:'Hutang & Piutang — '+(st.name||'Usaha'),note:'Per '+dmy(today())+'. Pembayaran hutang = kas keluar; pembayaran piutang = kas masuk.',widths:[13,20,28,32,16,13,16,16,14],rows:[[{h:'Tanggal'},{h:'Jenis'},{h:'Pihak'},{h:'Keterangan'},{h:'Jumlah (Rp)'},{h:'Jatuh tempo'},{h:'Sudah dibayar (Rp)'},{h:'Sisa (Rp)'},{h:'Status'}],...rows,[{b:'TOTAL'},null,null,null,{brp:ta},null,{brp:tp},{brp:tr},null]]},{name:'Riwayat Pembayaran',title:'Riwayat pembayaran',widths:[13,20,28,16,16,14],rows:[[{h:'Tanggal'},{h:'Jenis'},{h:'Pihak'},{h:'Metode'},{h:'Nominal (Rp)'},{h:'Arus kas'}],...pays]}],'hutang-piutang-'+today()+'.xlsx');toast('Laporan hutang & piutang siap diunduh')};

// ---- unduh Excel pengeluaran ----
$('exportExpenses').onclick=async()=>{const {from,to}=expenseRange(),{groups}=await getExpenseMasters(),st=(await all('settings')).find(x=>x.id==='main')||{};const es=(await all('expenses')).filter(x=>x.date>=from&&x.date<=to).sort((a,b)=>a.date.localeCompare(b.date)||(a.createdAt||0)-(b.createdAt||0));const grp=x=>groups[x.type]||defaultExpenseGroup(x.type),sum=l=>l.reduce((n,x)=>n+(Number(x.amount)||0),0);
const rows=es.map(e=>[{d:e.date},e.type||'Lainnya',EXP_GROUPS[grp(e)],e.name,Number(e.qty)||1,e.unit||'',{rp:Number(e.unitPrice)||0},{rp:Number(e.amount)||0},e.payment||'Tunai',e.employeeName||'',e.note||'']);
const byPay={};es.forEach(x=>{const m=x.payment||'Tunai';byPay[m]=(byPay[m]||0)+(Number(x.amount)||0)});const bahan=sum(es.filter(x=>grp(x)==='bahan')),oper=sum(es.filter(x=>grp(x)==='operasional')),gaji=sum(es.filter(x=>grp(x)==='gaji')),beban=sum(es.filter(x=>grp(x)==='beban'));
await exportXlsx([{name:'Pengeluaran',title:'Laporan Pengeluaran — '+(st.name||'Usaha'),note:'Periode '+dmy(from)+' s.d. '+dmy(to),widths:[13,18,20,28,8,10,16,16,16,18,28],rows:[[{h:'Tanggal'},{h:'Jenis'},{h:'Kelompok'},{h:'Item'},{h:'Qty'},{h:'Satuan'},{h:'Harga satuan (Rp)'},{h:'Nominal (Rp)'},{h:'Metode bayar'},{h:'Karyawan'},{h:'Keterangan'}],...rows,[{b:'TOTAL'},null,null,null,null,null,null,{brp:sum(es)},null,null,null]]},{name:'Ringkasan',title:'Ringkasan pengeluaran',widths:[34,18,40],rows:[[{h:'Komponen'},{h:'Nilai (Rp)'},{h:'Keterangan'}],['Belanja Bahan',{rp:bahan},'Bahan baku & belanja bahan'],['Belanja Operasional (langsung)',{rp:oper},'Gas, kemasan, dll.'],[{b:'HPP (pembelian)'},{brp:bahan+oper},'Bahan + Operasional; HPP aktual disesuaikan persediaan di menu Pembukuan'],['Beban Usaha Lain',{rp:beban},'Utilitas, transportasi (di luar HPP)'],['Gaji Karyawan',{rp:gaji},'Pembayaran gaji'],[{b:'Total pengeluaran'},{brp:sum(es)},es.length+' catatan'],[],[{h:'Metode bayar'},{h:'Nilai (Rp)'},{h:'Catatan'}],...Object.entries(byPay).sort((a,b)=>b[1]-a[1]).map(([m,v])=>[m,{rp:v},m==='Hutang'?'Belum mengurangi kas sampai dibayar':''])]}],'pengeluaran-'+from+'_'+to+'.xlsx');toast('Laporan pengeluaran siap diunduh')};

